const out = [];
for (const i of $input.all()) {
  const e = i.json;
  const match = `${e.description || ''} ${e.location || ''}`.match(/phone:\s*(\+?[0-9][0-9 ()-]{7,})/i);
  if (!match || !e.start?.dateTime) continue; // no phone found - skip
  const time = new Date(e.start.dateTime).toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' });
  out.push({ json: {
    to: match[1].replace(/[ ()-]/g, ''),
    body: `Reminder: your appointment \"${e.summary}\" is tomorrow at ${time}. Reply CANCEL if you can't make it.`
  } });
}
return out;
